process-fork.code:
#include <stdio.h>
#include <unistd.h>

int main(void) {
    int n = 0;
    pid_t a = fork();
    if (a == 0) {
        n = 1;
    }
    pid_t b = fork();
    if (b == 0) {
        n += 2;
    }
    printf("%d\n", n);
    return 0;
}

