void *worker(void *arg) {
    printf("%d\n", *(int *)arg);
    return NULL;
}

/* in main */
pthread_t t[3];
for (int i = 0; i < 3; i++) {
    pthread_create(&t[i], NULL, worker, &i);
}
for (int i = 0; i < 3; i++) {
    pthread_join(t[i], NULL);
}
